 renderGoal(state.score,st.target);
 $('board-label').textContent=`STAGE ${String(st.id).padStart(3,'0')} · ${st.cols} × ${st.rows}`;$('garden-frame').classList.toggle('dense',state.cols>=6);fitBoard();renderBoard(planted);
 $('forecast-label').textContent=isPlant?'오늘 수확 예상':'마지막 수확';$('forecast').innerHTML=`+${result?.total||0} <small>햇살</small>`;$('combos').textContent=columnBonus(result)?`↕ 같은 열 +${columnBonus(result)}`:result?.comboCount?`조합 효과 ${result.comboCount}곳`:state.version>=4?'같은 식물을 세로로 모아요':'이웃 효과를 만들어요';
 $('seed-cards').hidden=!isPlant||ready;$('ready-card').hidden=isPlant&&!ready;
 $('draft-title').textContent=state.phase==='over'?(passed()?'목표 달성! 다음 정원이 열렸어요':'이번엔 조금 아쉬웠어요'):state.phase==='evolve'?'어떤 모습으로 자랄까요?':state.phase==='upgrade'?'정원에 새 능력을 더해요':ready?'수확할 시간이에요':selected?`${seeds()[selected].name}, 어디에 심을까요?`:'씨앗 하나를 골라요';
 $('picks').textContent=isPlant?`오늘 ${state.placements} / ${picksToday(state)}`:state.phase==='evolve'?`진화 ${state.board.filter(t=>t?.evolution).length}송이`:`${state.upgrades.length}개 성장 보너스`;
 if(isPlant&&!ready)$('seed-cards').innerHTML=cardsHTML();
 if(state.phase==='over')$('ready-card').innerHTML=`<span aria-hidden="true">${passed()?'✿':'♧'}</span><div><strong>${passed()?`${st.id}단계 클리어`:`목표까지 ${st.target-state.score}점`}</strong><p>${passed()?'다음 단계에서 새로운 정원을 만나세요.':'같은 씨앗으로 배치와 조합을 바꿔 보세요.'}</p></div>`;
 else if(state.phase==='evolve')$('ready-card').innerHTML='<span aria-hidden="true">✦</span><div><strong>내 식물의 새로운 모습</strong><p>한 송이를 고르고, 두 모습 중 하나로 키워요.</p></div>';
 else if(state.phase==='upgrade')$('ready-card').innerHTML='<span aria-hidden="true">✦</span><div><strong>어떤 정원으로 키울까요?</strong><p>이번 단계 내내 유지되는 보너스를 골라요.</p></div>';
 else $('ready-card').innerHTML='<span aria-hidden="true">✦</span><div><strong>오늘의 정원이 준비됐어요</strong><p>수확하면 모든 식물이 한 번 더 자라요.</p></div>';
 $('tip').textContent=selected?(zoomMode?'원하는 구역을 누르면 크게 보고 심을 수 있어요.':'땅의 숫자 = 정원 전체의 수확 변화량'):state.phase==='over'?'결과를 보고 다음 전략을 정해 보세요.':state.phase==='evolve'?'정원의 식물을 누르거나 아래에서 진화를 골라요.':state.phase==='upgrade'?'성장 보너스는 이 단계가 끝날 때까지 유지돼요.':ready?'수확 전에는 되돌려서 자리를 바꿀 수 있어요.':'씨앗을 고른 뒤 빈 땅을 누르세요.';
